// 把多段文本各自折行后拼起来：段与段之间空一行，空段保留为一个空行。
export function joinFitted(paragraphs, maxWidth) {
  const lines = [];
  for (const paragraph of paragraphs) {
    if (lines.length > 0) lines.push("");
    const wrapped = wrap(paragraph, maxWidth);
    // wrap 对空段返回空数组，这里补成「一个空行」。
    if (wrapped.length > 0) lines.push(...wrapped);
    else lines.push("");
  }
  return lines.join("\n");
}

