// 把多段文本各自折行后拼起来：段与段之间空一行。
// 空段不会被丢弃（它前后的分隔空行照常保留），只是自身折不出行——
// wrap 对空段返回空数组，补上一行会多出一个换行。
export function joinFitted(paragraphs, maxWidth) {
  const lines = [];
  let index = 0;
  for (const paragraph of paragraphs) {
    if (index > 0) lines.push("");
    lines.push(...wrap(paragraph, maxWidth));
    index += 1;
  }
  return lines.join("\n");
}
